sealed class Factory(HttpClient client):IHttpClientFactory{public HttpClient CreateClient(string name)=>client;}
sealed class Fixture:HttpMessageHandler
{
 public string Body="{}";public HttpStatusCode Status=HttpStatusCode.OK;public Uri? Uri;public string? TokenBody,AccessToken;public int Calls,TokenRequests;
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;if(request.RequestUri!.Host=="api.amazon.com"){CheckMethod(request,HttpMethod.Post);TokenRequests++;TokenBody=await request.Content!.ReadAsStringAsync(ct);return new(HttpStatusCode.OK){Content=new StringContent("{\"access_token\":\"fixture-access-token\",\"token_type\":\"bearer\",\"expires_in\":3600}")};}CheckMethod(request,HttpMethod.Get);Uri=request.RequestUri;AccessToken=request.Headers.GetValues("x-amz-access-token").Single();return new(Status){Content=new StringContent(Body)};}
 private static void CheckMethod(HttpRequestMessage request,HttpMethod method){if(request.Method!=method)throw new Exception("Unexpected external write");}
